(function() {
  const metricBtns = document.querySelectorAll('.metric-btn');
  const metricDisplays = document.querySelectorAll('.metric-display');

  metricBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      metricBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      metricDisplays.forEach(display => display.classList.add('hidden'));
      document.getElementById(`metric-${btn.dataset.metric}`).classList.remove('hidden');

      drawChart(btn.dataset.metric);
    });
  });

  function drawChart(metric) {
    const canvas = document.getElementById(`${metric}Chart`);
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 教学示例数据，非真实训练权重
    const teachingData = {
      sentiment: { labels: ['基线', 'AI 辅助'], values: [0.14, 0.32], color: '#2C5282' },
      attrition: { labels: ['基线', 'AI 辅助'], values: [0.25, 0.15], color: '#DD6B20' },
      escalation: { labels: ['基线', 'AI 辅助'], values: [0.04, 0.03], color: '#38A169' }
    };

    const data = teachingData[metric];
    if (!data) return;

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const maxValue = Math.max(...data.values) * 1.2;

    // 绘制坐标轴
    ctx.strokeStyle = '#E2E8F0';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 绘制柱状图
    const barWidth = chartWidth / data.values.length / 2;
    data.values.forEach((value, index) => {
      const barHeight = (value / maxValue) * chartHeight;
      const x = padding + index * (chartWidth / data.values.length) + barWidth / 2;
      const y = canvas.height - padding - barHeight;

      ctx.fillStyle = data.color;
      ctx.fillRect(x, y, barWidth, barHeight);

      // 绘制数值标签
      ctx.fillStyle = '#2D3748';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(value.toFixed(2), x + barWidth / 2, y - 10);

      // 绘制类别标签
      ctx.fillText(data.labels[index], x + barWidth / 2, canvas.height - padding + 20);
    });

    // 添加教学说明
    ctx.fillStyle = '#718096';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText('教学示例，非论文训练权重', canvas.width - padding, padding);
  }

  // 初始化第一个图表
  drawChart('sentiment');

  // 来源按钮事件
  document.querySelectorAll('.source-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      // 由内核处理来源跳转
      console.log('Source request:', btn.dataset.source);
    });
  });
})();
